import axios from 'axios';

export default async function handler(req, res) {
    // CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type');

    if (req.method === 'OPTIONS') {
        return res.status(200).end();
    }

    if (req.method !== 'POST') {
        return res.status(405).json({ error: "Method not allowed" });
    }

    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ error: "Missing JWT Token" });
    }

    // Garena ka domain
    const targetUrl = "https://clientbp.ggpolarbear.com/GetLoginData"; 
    
    // Payload
    const payload = Buffer.from('', 'base64');

    try {
        const response = await axios.post(targetUrl, payload, {
            headers: {
                'Authorization': authHeader,
                'X-Unity-Version': '2018.4.11f1',
                'X-GA': 'v1 1',
                'ReleaseVersion': 'OB55',
                'Content-Type': 'application/x-www-form-urlencoded',
                'User-Agent': 'Dalvik/2.1.0 (Linux; Android)',
                'Content-Length': payload.length
            },
            validateStatus: () => true, // 401/500 pe bhi crash na ho
            timeout: 10000 
        });
        
        res.status(response.status).send(response.data);
    } catch (error) {
        res.status(500).json({ error: "Axios Error", details: error.message, code: error.code });
    }
}
